--
-- Bẫy `friend_requests`
--
DELIMITER $$
CREATE TRIGGER `after_friend_request_accepted` AFTER UPDATE ON `friend_requests` FOR EACH ROW BEGIN
    IF NEW.status = 'accepted' AND OLD.status = 'pending' THEN
        INSERT IGNORE INTO friendships (user1ID, user2ID) 
        VALUES (
            LEAST(NEW.fromUserID, NEW.toUserID), 
            GREATEST(NEW.fromUserID, NEW.toUserID)
        );
    END IF;
END
$$
DELIMITER ;

